/* ==========================================================================
   11. 上状态栏（#080830 午夜蓝 × #405880 钢蓝 × #98B0D0 雾蓝 × #B8B8B8 银灰 + 详细调节注释）
   ==========================================================================
   【上状态栏整体调节总指南】：
   1. 整体往下/往上移动：
      - 调第一行（返回键+角色名+右侧按钮）：修改下方 `.glass-header` 的 `margin-top: 8px`（改大如 16px 往下移，改小如 0px 往上移）。
      - 调下半部分（大头像+粉丝数+FOLLOWING+签名栏）：同时修改 `.header-avatar-container` 的 `bottom: 40px`、`.chat-header-custom::after` 的 `bottom: 4px` 以及 `.chat-header-custom::before` 的 `bottom: 7px`（三个数值同步加减相同的 px，即可一起上下平移）。
   2. 调节上状态栏总高度（与聊天消息列表的距离）：
      - 修改 `.chat-header-custom` 的 `padding-bottom: 96px`（改大则顶部区域变高、聊天消息往下退；改小则聊天消息往上靠）。
   ========================================================================== */

/* 11.1 顶部整体外层容器 */
.chat-detail-screen .chat-header-custom {
  position: relative !important;
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  border-top: none !important;
  border-bottom: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  --header-btn-gap: 6px !important; /* 【调节】右上角铃铛与三个点按钮之间的水平间距 */
  padding-bottom: 96px !important;  /* 【调节】上状态栏下半部分预留高度：改大整体变高，改小整体变矮 */
  height: auto !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  z-index: auto !important;
}

/* ★ 11.1-B 上状态栏底部 NOTE 签名文字（直接读取代码最开头的 --header-note-text 变量，含防隐身保护！） */
.chat-detail-screen .chat-header-custom::before {
  content: var(--header-note-text, '一滴淚砸下來 重了會被責怪 輕了會被忽視') !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
  position: absolute !important;
  left: 53px !important;            /* 【调节】NOTE 签名文字左右位置（位于左侧 NOTE 小框右边，改大往右移，改小往左移） */
  right: 52px !important;           /* 【调节】右侧留出 ♡ 520 的空间，防止文字过长撞到右侧爱心数字 */
  bottom: 7px !important;           /* 【调节】NOTE 签名文字上下位置（与下方 ::after 的 bottom: 4px 同步加减即可上下移动） */
  height: 13px !important;
  line-height: 13px !important;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang TC", "PingFang SC", "Songti TC", sans-serif !important;
  font-size: 9px !important;        /* 【调节】NOTE 签名文字字号大小 */
  font-weight: 600 !important;
  color: #080830 !important;        /* 【调节】NOTE 签名文字颜色 */
  -webkit-text-fill-color: #080830 !important;
  letter-spacing: 0.2px !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  pointer-events: none !important;
  z-index: 15 !important;
}

/* 11.2 顶栏第一行导航条（包含左返回键、中间名字、右铃铛和三个点） */
.chat-detail-screen .glass-header {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding-left: 10px !important;    /* 【调节】第一行左侧距离屏幕左边缘的距离（改大往右缩） */
  padding-right: 10px !important;   /* 【调节】第一行右侧距离屏幕右边缘的距离（改大往左缩） */
  margin-top: 8px !important;       /* 【调节】第一行整体上下位置：数值改大往下移，改小或负数往上移 */
  --header-btn-gap: 6px !important; /* 【调节】右侧功能按钮之间的间距 */
}

/* 隐藏系统默认副标题 */
.chat-detail-screen .chat-header-subtitle {
  display: none !important;
}

/* 11.3 顶栏 3 个圆形按钮（左返回箭头 .header-btn-back、右铃铛 .header-btn-video、右三个点 .header-btn-info）：#EBF1F8 冰白底 + #080830 描边 */
.chat-detail-screen .header-btn-back,
.chat-detail-screen .header-btn-video,
.chat-detail-screen .header-btn-info {
  position: relative !important;
  width: 28px !important;           /* 【调节】圆形按钮宽度（需与下方 min/max-width 同步改） */
  height: 28px !important;          /* 【调节】圆形按钮高度（需与下方 min/max-height 同步改） */
  min-width: 28px !important;
  max-width: 28px !important;
  min-height: 28px !important;
  max-height: 28px !important;
  aspect-ratio: 1 / 1 !important;
  border-radius: 50% !important;
  background: #EBF1F8 !important;
  border: 1.2px solid #080830 !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  box-sizing: border-box !important;
  flex-shrink: 0 !important;
}

.chat-detail-screen .header-btn-back {
  margin-right: 8px !important;     /* 【调节】左返回键与角色昵称之间的左右间距 */
  color: #080830 !important;
}

.chat-detail-screen .header-btn-back > svg,
.chat-detail-screen .header-btn-video > svg,
.chat-detail-screen .header-btn-info > svg {
  display: none !important;
}

/* 左返回箭头图标 */
.chat-detail-screen .header-btn-back::before {
  content: '' !important;
  position: absolute !important;
  inset: 0 !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
