  right: 12px !important;           /* 【调节】SVG 信息面板距离屏幕右边的距离 */
  bottom: 4px !important;           /* 【调节】SVG 信息面板上下位置：改大往上移，改小往下移（移动时请同步加减上方 .header-avatar-container 和 ::before 的 bottom 值） */
  height: 88px !important;          /* 【调节】SVG 面板容器高度 */
