/* 打字指示器气泡容器清除默认底色 */
.nuo-typing-bubble {
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  padding: 0 !important;
}

/* 隐藏原始打字圆点 */
.nuo-typing-indicator .typing-dot {
  display: none !important;
}

/* 打字指示器外层布局容器 */
.nuo-typing-indicator {
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  padding: 4px 0 !important;
}

/* 耳机线与 CD 光盘轻柔摇摆浮动动画关键帧 */
@keyframes sprout-sway {
  0%, 100% { transform: rotate(-3deg) translateY(0px); }
  25% { transform: rotate(2deg) translateY(-2.5px); }
  50% { transform: rotate(-1.5deg) translateY(-4px); }
  75% { transform: rotate(3deg) translateY(-1.5px); }
}

/* 清除打字气泡的 ::after 伪元素 */
.nuo-typing-bubble::after {
  content: none !important;
}

